import path from "node:path";
/** AEM / EDS site repo root (parent of mcp-apps/pixel-guard). */
export const REPO_ROOT = path.resolve(import.meta.dirname, process.env.PIXEL_GUARD_REPO_ROOT ?? "../..");
/** Playwright HTML report directory (generated by `npm run test:visual:*` in the repo). */
export const PLAYWRIGHT_REPORT_DIR = path.resolve(process.env.PLAYWRIGHT_REPORT_DIR ?? path.join(REPO_ROOT, "playwright-report"));
export const PLAYWRIGHT_REPORT_INDEX = path.join(PLAYWRIGHT_REPORT_DIR, "index.html");
